TracingInstanceAsyncWaiter::TracingInstanceAsyncWaiter(
    TracingInstance* proxy) : proxy_(proxy) {}

TracingInstanceAsyncWaiter::~TracingInstanceAsyncWaiter() = default;

void TracingInstanceAsyncWaiter::QueryAvailableCategories(
    std::vector<std::string>* out_categories) {
  base::RunLoop loop;
  proxy_->QueryAvailableCategories(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<std::string>* out_categories
,
             const std::vector<std::string>& categories) {*out_categories = std::move(categories);
            loop->Quit();
          },
          &loop,
          out_categories));
  loop.Run();
}

std::vector<std::string> TracingInstanceAsyncWaiter::QueryAvailableCategories(
    ) {
  std::vector<std::string> async_wait_result;
  QueryAvailableCategories(&async_wait_result);
  return async_wait_result;
}

void TracingInstanceAsyncWaiter::StartTracing(
    const std::vector<std::string>& categories, ::mojo::ScopedHandle socket, bool* out_success) {
  base::RunLoop loop;
  proxy_->StartTracing(std::move(categories),std::move(socket),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool TracingInstanceAsyncWaiter::StartTracing(
    const std::vector<std::string>& categories, ::mojo::ScopedHandle socket) {
  bool async_wait_result;
  StartTracing(std::move(categories),std::move(socket),&async_wait_result);
  return async_wait_result;
}

void TracingInstanceAsyncWaiter::StopTracing(
    bool* out_success) {
  base::RunLoop loop;
  proxy_->StopTracing(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool TracingInstanceAsyncWaiter::StopTracing(
    ) {
  bool async_wait_result;
  StopTracing(&async_wait_result);
  return async_wait_result;
}






